<div class="grid lg:grid-cols-3 gap-5"><section class="border bg-white rounded-xl p-5"><h2 class="font-bold mb-4">Crear pedido</h2><form method="POST" action="<?php echo e(route('orders.store')); ?>" x-data="{lines:[{product_id:'',quantity:1}]}" class="space-y-3"><?php echo csrf_field(); ?><label class="block">Cliente<select name="customer_id" class="w-full border rounded-lg p-3"><option value="">Venta sin cliente registrado</option><?php $__currentLoopData = $customers; $__env->addLoop($__currentLoopData); foreach($__currentLoopData as $customer): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); ?><option value="<?php echo e($customer->id); ?>"><?php echo e($customer->name); ?></option><?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); ?></select></label><label class="block">Método de pago<select name="payment_method" class="w-full border rounded-lg p-3"><option value="">No especificado</option><option>Efectivo</option><option>Yape</option><option>Plin</option><option>Transferencia</option><option>Tarjeta</option></select></label><h3 class="font-semibold">Productos</h3><template x-for="(line,i) in lines" :key="i"><div class="border rounded-lg p-3 space-y-2"><select :name="'items['+i+'][product_id]'" x-model="line.product_id" required class="w-full border rounded-lg p-2"><option value="">Seleccionar producto</option><?php $__currentLoopData = $products; $__env->addLoop($__currentLoopData); foreach($__currentLoopData as $product): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); ?><option value="<?php echo e($product->id); ?>" <?php if($product->stock<1): echo 'disabled'; endif; ?>><?php echo e($product->name); ?> — S/ <?php echo e(number_format($product->sale_price,2)); ?> — stock <?php echo e($product->stock); ?></option><?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); ?></select><div class="flex gap-2"><input type="number" min="1" required x-model="line.quantity" :name="'items['+i+'][quantity]'" class="w-full border rounded-lg p-2"><button type="button" @click="lines.splice(i,1)" :disabled="lines.length===1" class="text-red-600">Quitar</button></div></div></template><button type="button" @click="lines.push({product_id:'',quantity:1})" class="text-emerald-700 font-semibold">+ Agregar producto</button><label class="block">Notas<textarea name="notes" class="w-full border rounded-lg p-3"></textarea></label><button class="w-full rounded-lg bg-emerald-700 text-white p-3">Guardar pedido</button></form></section>
<section class="lg:col-span-2 border bg-white rounded-xl overflow-x-auto"><table class="w-full text-sm"><thead class="bg-slate-50"><tr><th class="p-3 text-left">Pedido</th><th>Cliente / Detalle</th><th>Total</th><th>Estado</th><th>Acciones</th></tr></thead><tbody><?php $__empty_1 = true; $__currentLoopData = $orders; $__env->addLoop($__currentLoopData); foreach($__currentLoopData as $order): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); $__empty_1 = false; ?><tr class="border-t"><td class="p-3"><?php echo e($order->code); ?><div class="text-xs text-slate-500"><?php echo e($order->created_at?->format('d/m/Y H:i')); ?></div></td><td class="p-3"><?php echo e($order->customer?->name ?? 'Consumidor final'); ?><details><summary class="cursor-pointer text-emerald-700">Ver productos</summary><?php $__currentLoopData = $order->items; $__env->addLoop($__currentLoopData); foreach($__currentLoopData as $item): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); ?><div><?php echo e($item->product_name); ?> × <?php echo e($item->quantity); ?> — S/ <?php echo e(number_format($item->subtotal,2)); ?></div><?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); ?><div>Pago: <?php echo e($order->payment_method ?: '—'); ?></div><div><?php echo e($order->notes); ?></div></details></td><td class="p-3 font-bold">S/ <?php echo e(number_format($order->total,2)); ?></td><td class="p-3"><?php echo e(['pending'=>'Pendiente','completed'=>'Completado','cancelled'=>'Cancelado'][$order->status]??$order->status); ?></td><td class="p-3"><?php if($order->status==='pending'): ?><form action="<?php echo e(route('orders.update',$order)); ?>" method="POST" class="space-y-2"><?php echo csrf_field(); ?> <?php echo method_field('PATCH'); ?><button name="status" value="completed" class="text-emerald-700">Completar</button><button name="status" value="cancelled" onclick="return confirm('¿Cancelar y devolver stock?')" class="block text-red-600">Cancelar</button></form><?php elseif($order->status==='completed'): ?><form action="<?php echo e(route('orders.update',$order)); ?>" method="POST"><?php echo csrf_field(); ?> <?php echo method_field('PATCH'); ?><button name="status" value="cancelled" onclick="return confirm('¿Cancelar venta y devolver stock?')" class="text-red-600">Cancelar</button></form><?php else: ?> — <?php endif; ?></td></tr><?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); if ($__empty_1): ?><tr><td colspan="5" class="p-6 text-center text-slate-500">Todavía no hay pedidos.</td></tr><?php endif; ?></tbody></table><div class="p-4"><?php echo e($orders->links()); ?></div></section></div></div>
